cat <<'EOF' > /workspace/tui.go
package main

import (
	"fmt"
	"os"
	"os/exec"
	"os/signal"
	"path/filepath"
	"strings"
	"syscall"
	"time"
	"unsafe"
)

type termios struct {
	Iflag  uint32
	Oflag  uint32
	Cflag  uint32
	Lflag  uint32
	Cc     [32]byte
	Ispeed uint32
	Ospeed uint32
}

type winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

func makeRaw(fd int) (*termios, error) {
	var oldState termios
	if _, _, err := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), syscall.TCGETS, uintptr(unsafe.Pointer(&oldState))); err != 0 {
		return nil, err
	}
	newState := oldState
	newState.Iflag &^= (syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON)
	newState.Oflag &^= syscall.OPOST
	newState.Lflag &^= (syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN)
	newState.Cflag &^= (syscall.CSIZE | syscall.PARENB)
	newState.Cflag |= syscall.CS8

	if _, _, err := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), syscall.TCSETS, uintptr(unsafe.Pointer(&newState))); err != 0 {
		return nil, err
	}
	return &oldState, nil
}

func restoreTerm(fd int, state *termios) {
	syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), syscall.TCSETS, uintptr(unsafe.Pointer(state)))
}

func getWinSize(fd int) (int, int) {
	var ws winsize
	if _, _, err := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), syscall.TIOCGWINSZ, uintptr(unsafe.Pointer(&ws))); err == 0 {
		return int(ws.Col), int(ws.Row)
	}
	return 80, 24
}

type appState struct {
	focusedPanel int
	showPopup    bool
	repoName     string
	branchName   string
	files        []string
	branches     []string
	commits      []string
	stashes      []string
	fileIdx      int
	branchIdx    int
	commitIdx    int
	stashIdx     int
	diffLines    []string
}

func runTUI(opts cliOptions) {
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return
	}
	defer tty.Close()

	fd := int(tty.Fd())
	oldState, err := makeRaw(fd)
	if err == nil {
		defer restoreTerm(fd, oldState)
	}

	tty.WriteString("\x1b[?1049h\x1b[?25l")
	defer tty.WriteString("\x1b[?25h\x1b[?1049l")

	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)

	app := initAppState(opts)

	drawScreen(tty, app)

	buf := make([]byte, 32)
	for {
		select {
		case <-sigChan:
			return
		default:
		}

		n, err := tty.Read(buf)
		if err != nil || n == 0 {
			time.Sleep(10 * time.Millisecond)
			continue
		}

		input := string(buf[:n])

		if app.showPopup {
			if input == "\r" || input == "\n" || input == "\x1b" || input == "q" || input == "Q" {
				app.showPopup = false
				drawScreen(tty, app)
			}
			continue
		}

		if input == "q" || input == "Q" || input == "\x03" {
			return
		} else if input == "1" {
			app.focusedPanel = 1
		} else if input == "2" {
			app.focusedPanel = 2
		} else if input == "3" {
			app.focusedPanel = 3
		} else if input == "4" {
			app.focusedPanel = 4
		} else if input == "5" {
			app.focusedPanel = 5
		} else if input == "\t" {
			app.focusedPanel = (app.focusedPanel % 5) + 1
		} else if input == "j" || input == "\x1b[B" {
			moveSelection(app, 1)
		} else if input == "k" || input == "\x1b[A" {
			moveSelection(app, -1)
		}

		drawScreen(tty, app)
	}
}

func initAppState(opts cliOptions) *appState {
	app := &appState{
		focusedPanel: 1,
		showPopup:    true,
	}

	if opts.gitArg != "" {
		switch strings.ToLower(opts.gitArg) {
		case "status":
			app.focusedPanel = 1
		case "branch", "branches":
			app.focusedPanel = 3
		case "log", "commits":
			app.focusedPanel = 4
		case "stash":
			app.focusedPanel = 5
		}
	}

	pwd, err := os.Getwd()
	if err == nil {
		app.repoName = filepath.Base(pwd)
	}
	if app.repoName == "" {
		app.repoName = "workspace"
	}

	out, err := exec.Command("git", "branch", "--show-current").Output()
	if err == nil {
		app.branchName = strings.TrimSpace(string(out))
	}
	if app.branchName == "" {
		app.branchName = "master"
	}

	out, err = exec.Command("git", "status", "--porcelain").Output()
	if err == nil {
		lines := strings.Split(string(out), "\n")
		for _, line := range lines {
			if strings.TrimSpace(line) != "" {
				app.files = append(app.files, line)
			}
		}
	}

	out, err = exec.Command("git", "branch", "--format=%(refname:short)").Output()
	if err == nil {
		lines := strings.Split(string(out), "\n")
		for _, line := range lines {
			if strings.TrimSpace(line) != "" {
				app.branches = append(app.branches, line)
			}
		}
	}

	out, err = exec.Command("git", "log", "--oneline", "-n", "20").Output()
	if err == nil {
		lines := strings.Split(string(out), "\n")
		for _, line := range lines {
			if strings.TrimSpace(line) != "" {
				app.commits = append(app.commits, line)
			}
		}
	}

	out, err = exec.Command("git", "diff").Output()
	if err == nil {
		app.diffLines = strings.Split(string(out), "\n")
	}

	return app
}

func moveSelection(app *appState, dir int) {
	switch app.focusedPanel {
	case 2:
		if len(app.files) > 0 {
			app.fileIdx = (app.fileIdx + dir + len(app.files)) % len(app.files)
		}
	case 3:
		if len(app.branches) > 0 {
			app.branchIdx = (app.branchIdx + dir + len(app.branches)) % len(app.branches)
		}
	case 4:
		if len(app.commits) > 0 {
			app.commitIdx = (app.commitIdx + dir + len(app.commits)) % len(app.commits)
		}
	case 5:
		if len(app.stashes) > 0 {
			app.stashIdx = (app.stashIdx + dir + len(app.stashes)) % len(app.stashes)
		}
	}
}

func drawScreen(tty *os.File, app *appState) {
	cols, rows := getWinSize(int(tty.Fd()))
	if cols < 20 || rows < 10 {
		return
	}

	var sb strings.Builder
	sb.WriteString("\x1b[H\x1b[2J")

	leftWidth := cols / 3
	rightWidth := cols - leftWidth

	p1H := 3
	p5H := 3
	remH := rows - 2 - p1H - p5H
	p2H := remH / 3
	p3H := remH / 3
	p4H := remH - p2H - p3H

	drawBox(&sb, 0, 0, leftWidth, p1H, "[1] Status", app.focusedPanel == 1)
	writeAt(&sb, 1, 1, truncateString(fmt.Sprintf("%s → %s", app.repoName, app.branchName), leftWidth-3))

	drawBox(&sb, 0, p1H, leftWidth, p2H, "[2] Files - Worktrees - Submodules", app.focusedPanel == 2)
	for i, f := range app.files {
		if i >= p2H-2 {
			break
		}
		prefix := "  "
		if i == app.fileIdx && app.focusedPanel == 2 {
			prefix = "> "
		}
		writeAt(&sb, p1H+1+i, 1, truncateString(prefix+f, leftWidth-3))
	}

	drawBox(&sb, 0, p1H+p2H, leftWidth, p3H, "[3] Local branches - Remotes - Tags", app.focusedPanel == 3)
	for i, b := range app.branches {
		if i >= p3H-2 {
			break
		}
		prefix := "  "
		if b == app.branchName {
			prefix = "* "
		}
		if i == app.branchIdx && app.focusedPanel == 3 {
			prefix = "> "
		}
		writeAt(&sb, p1H+p2H+1+i, 1, truncateString(prefix+b, leftWidth-3))
	}

	drawBox(&sb, 0, p1H+p2H+p3H, leftWidth, p4H, "[4] Commits - Reflog", app.focusedPanel == 4)
	for i, c := range app.commits {
		if i >= p4H-2 {
			break
		}
		prefix := "  "
		if i == app.commitIdx && app.focusedPanel == 4 {
			prefix = "> "
		}
		writeAt(&sb, p1H+p2H+p3H+1+i, 1, truncateString(prefix+c, leftWidth-3))
	}

	drawBox(&sb, 0, p1H+p2H+p3H+p4H, leftWidth, p5H, "[5] Stash", app.focusedPanel == 5)

	mainH := rows - 4
	drawBox(&sb, leftWidth, 0, rightWidth, mainH, "[0] Unstaged changes", false)
	for i, line := range app.diffLines {
		if i >= mainH-2 {
			break
		}
		writeAt(&sb, 1+i, leftWidth+1, truncateString(line, rightWidth-3))
	}

	cmdLogH := 3
	drawBox(&sb, leftWidth, mainH, rightWidth, cmdLogH, "Command log", false)

	bottomY := rows - 1
	bottomText := "Stage: <space> | Commit: c | Stash: s | Discard: d | Reset: D | Keybindings: ?              Donate Ask Question " + version
	writeAt(&sb, bottomY, 0, truncateString(bottomText, cols))

	if app.showPopup {
		popW := 80
		popH := 18
		if popW > cols-4 {
			popW = cols - 4
		}
		if popH > rows-4 {
			popH = rows - 4
		}
		popX := (cols - popW) / 2
		popY := (rows - popH) / 2

		clearBox(&sb, popX, popY, popW, popH)
		drawBox(&sb, popX, popY, popW, popH, "", true)

		popupLines := []string{
			"Thanks for using lazygit! Seriously you rock. Three things to share with you:",
			"",
			" 1) If you want to learn about lazygit's features, watch this vid:",
			"      https://youtu.be/CPLdltN7wgE",
			"",
			" 2) Be sure to read the latest release notes at:",
			"      https://github.com/jesseduffield/lazygit/releases",
			"",
			" 3) If you're using git, that makes you a programmer! With your help we can",
			"make",
			"    lazygit better, so consider becoming a contributor and joining the fun at",
			"      https://github.com/jesseduffield/lazygit",
			"    Or even just star the repo to share the love!",
			"",
			" 4) If lazygit has made your life easier, you can say thanks by clicking the",
			"    donate button at the bottom right. Donation does not grant priority",
			"support,",
			"    but it is much appreciated.",
			"",
			"Press <enter> to get started.",
		}

		for i, pLine := range popupLines {
			if i >= popH-2 {
				break
			}
			writeAt(&sb, popY+1+i, popX+2, truncateString(pLine, popW-4))
		}
	}

	tty.WriteString(sb.String())
}

func drawBox(sb *strings.Builder, x, y, w, h int, title string, active bool) {
	if w < 2 || h < 2 {
		return
	}

	tl, tr, bl, br, hor, ver := "╭", "╮", "╰", "╯", "─", "│"

	sb.WriteString(fmt.Sprintf("\x1b[%d;%dH", y+1, x+1))
	sb.WriteString(tl)
	if title != "" {
		sb.WriteString("─" + title + "─")
		titleLen := len(title) + 2
		for i := 0; i < w-2-titleLen; i++ {
			sb.WriteString(hor)
		}
	} else {
		for i := 0; i < w-2; i++ {
			sb.WriteString(hor)
		}
	}
	sb.WriteString(tr)

	for i := 1; i < h-1; i++ {
		sb.WriteString(fmt.Sprintf("\x1b[%d;%dH", y+1+i, x+1))
		sb.WriteString(ver)
		sb.WriteString(fmt.Sprintf("\x1b[%d;%dH", y+1+i, x+w))
		sb.WriteString(ver)
	}

	sb.WriteString(fmt.Sprintf("\x1b[%d;%dH", y+h, x+1))
	sb.WriteString(bl)
	for i := 0; i < w-2; i++ {
		sb.WriteString(hor)
	}
	sb.WriteString(br)
}

func clearBox(sb *strings.Builder, x, y, w, h int) {
	spaces := strings.Repeat(" ", w)
	for i := 0; i < h; i++ {
		sb.WriteString(fmt.Sprintf("\x1b[%d;%dH", y+1+i, x+1))
		sb.WriteString(spaces)
	}
}

func writeAt(sb *strings.Builder, row, col int, text string) {
	sb.WriteString(fmt.Sprintf("\x1b[%d;%dH%s", row+1, col+1, text))
}

func truncateString(s string, maxLen int) string {
	if maxLen <= 0 {
		return ""
	}
	if len(s) > maxLen {
		return s[:maxLen]
	}
	return s
}
EOF"}

