func getHelpText() string {
	return `executable

  Usage:
    executable [git-arg]

  Positional Variables: 
    git-arg   Panel to focus upon opening lazygit. Accepted values (based on git terminology): status, branch, log, stash. Ignored if --filter arg is passed.
  Flags: 
    -h --help               Displays help with available flag, subcommand, and positional value parameters.
    -p --path               Path of git repo. (equivalent to --work-tree=<path> --git-dir=<path>/.git/)
    -f --filter             Path to filter on in ` + "`" + `git log -- <path>` + "`" + `. When in filter mode, the commits, reflog, and stash are filtered based on the given path, and some operations are restricted
    -v --version            Print the current version
    -d --debug              Run in debug mode with logging (see --logs flag below). Use the LOG_LEVEL env var to set the log level (debug/info/warn/error)
    -l --logs               Tail lazygit logs (intended to be used when ` + "`" + `lazygit --debug` + "`" + ` is called in a separate terminal tab)
       --profile            Start the profiler and serve it on http port 6060. See CONTRIBUTING.md for more info.
    -c --config             Print the default config
    -cd --print-config-dir   Print the config directory
    -ucd --use-config-dir     override default config directory with provided directory
    -w --work-tree          equivalent of the --work-tree git argument
    -g --git-dir            equivalent of the --git-dir git argument
    -ucf --use-config-file    Comma separated list to custom config file(s)
    -sm --screen-mode        The initial screen-mode, which determines the size of the focused panel. Valid options: 'normal' (default), 'half', 'full'

`
}

func printVersion() {
	gitVer := getGitVersion()
	fmt.Printf("commit=%s, build date=%s, build source=%s, version=%s, os=%s, arch=%s, git version=%s\n",
		commit, date, buildSource, version, runtime.GOOS, runtime.GOARCH, gitVer)
}

func getGitVersion() string {
	out, err := exec.Command("git", "--version").Output()
	if err != nil {
		return ""
	}
	s := strings.TrimSpace(string(out))
	s = strings.TrimPrefix(s, "git version ")
	return s
}

func getConfigDir(useConfigDir string) string {
	if useConfigDir != "" {
		return useConfigDir
	}
	if xdg := os.Getenv("XDG_CONFIG_HOME"); xdg != "" {
		return filepath.Join(xdg, "lazygit")
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return filepath.Join(".config", "lazygit")
	}
	return filepath.Join(home, ".config", "lazygit")
}

func getStateDir() string {
	if xdg := os.Getenv("XDG_STATE_HOME"); xdg != "" {
		return filepath.Join(xdg, "lazygit")
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return filepath.Join(".local", "state", "lazygit")
	}
	return filepath.Join(home, ".local", "state", "lazygit")
}

func tailLogs() {
	logPath := filepath.Join(getStateDir(), "development.log")
	fmt.Printf("Tailing log file %s\n\n", logPath)

	f, err := os.Open(logPath)
	if err != nil {
		now := time.Now().Format("2006/01/02 15:04:05")
		fmt.Fprintf(os.Stderr, "%s Log file does not exist. Run `lazygit --debug` first to create the log file\n", now)
		os.Exit(1)
	}
	defer f.Close()

	io.Copy(os.Stdout, f)

	buf := make([]byte, 1024)
	for {
		n, err := f.Read(buf)
		if n > 0 {
			os.Stdout.Write(buf[:n])
		} else {
			time.Sleep(100 * time.Millisecond)
		}
	}
}

func isGitRepository() bool {
	cmd := exec.Command("git", "rev-parse", "--is-inside-work-tree")
	err := cmd.Run()
	return err == nil
}

func isTTY() bool {
	fi, err := os.Stdin.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func main() {
	args := os.Args[1:]

	opts, err := parseCLIArgs(args)
	if err != nil {
		fmt.Print(getHelpText())
		fmt.Println(err.Error())
		os.Exit(2)
	}

	if opts.help {
		fmt.Print(getHelpText())
		os.Exit(0)
	}

	if opts.version {
		printVersion()
		os.Exit(0)
	}

	if opts.config {
		fmt.Print(string(defaultConfig))
		os.Exit(0)
	}

	if opts.printConfigDir {
		fmt.Println(getConfigDir(opts.useConfigDir))
		os.Exit(0)
	}

	if opts.logs {
		tailLogs()
		os.Exit(0)
	}

	if opts.path != "" {
		if err := os.Chdir(opts.path); err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
	} else if opts.workTree != "" {
		if err := os.Chdir(opts.workTree); err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
	}

	termEnv := os.Getenv("TERM")
	if termEnv == "" {
		now := time.Now().Format("2006/01/02 15:04:05")
		fmt.Fprintf(os.Stderr, "%s An error occurred! Please create an issue at: https://github.com/jesseduffield/lazygit/issues\n\n*fmt.wrapError terminal entry not found: term not set\ngithub.com/jesseduffield/lazygit/pkg/app/app.go:55 (0xc91c3f)\ngithub.com/jesseduffield/lazygit/pkg/app/entry_point.go:177 (0xc93eb6)\ngithub.com/jesseduffield/lazygit/main.go:23 (0xc95258)\ninternal/runtime/atomic/types.go:194 (0x44a51d)\nruntime/asm_amd64.s:1693 (0x4888a1)\n", now)
		os.Exit(1)
	}

	if !isGitRepository() {
		if isTTY() {
			fmt.Print("Not in a git repository. Create a new git repository? (y/N): ")
			var ans string
			fmt.Scanln(&ans)
			ans = strings.TrimSpace(strings.ToLower(ans))
			if ans == "y" || ans == "yes" {
				cmd := exec.Command("git", "init")
				cmd.Stdout = os.Stdout
				cmd.Stderr = os.Stderr
				if err := cmd.Run(); err != nil {
					os.Exit(1)
				}
			} else {
				fmt.Println("Must open lazygit in a git repository. No valid recent repositories. Exiting.")
				os.Exit(1)
			}
		} else {
			fmt.Println("Not in a git repository. Create a new git repository? (y/N): Must open lazygit in a git repository. No valid recent repositories. Exiting.")
			os.Exit(1)
		}
	}

	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		now := time.Now().Format("2006/01/02 15:04:05")
		fmt.Fprintf(os.Stderr, "%s An error occurred! Please create an issue at: https://github.com/jesseduffield/lazygit/issues\n\n*fs.PathError open /dev/tty: no such device or address\ngithub.com/jesseduffield/lazygit/pkg/app/app.go:55 (0xc91c3f)\ngithub.com/jesseduffield/lazygit/pkg/app/entry_point.go:177 (0xc93eb6)\ngithub.com/jesseduffield/lazygit/main.go:23 (0xc95258)\ninternal/runtime/atomic/types.go:194 (0x44a51d)\nruntime/asm_amd64.s:1693 (0x4888a1)\n", now)
		os.Exit(1)
	}
	_ = tty
	tty.Close()

	runTUI(opts)
